contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    //  - withdrawValue: amount the owner (this contract) will ask C to withdraw
    function run(uint withdrawValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // this contract deployed C, so InvMutTest is owner of c; ensure it has some balance to receive withdrawals
        // require not strictly necessary but ensures we can receive funds if withdraw transfers succeed
        require(address(this).balance >= 0);

        // observe before-values
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeCbal = address(c).balance;

        // Owner (this contract) invokes withdraw on c; keep call as a top-level statement
        bool reverted;
        c.withdraw(withdrawValue); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterCbal = address(c).balance;

        // General rule:
        // Calling withdraw as owner never increases c's balance, and it does not mutate depositsCount.
        // (i.e., afterCbal <= beforeCbal and afterDeposits == beforeDeposits)
        assert(afterCbal <= beforeCbal && afterDeposits == beforeDeposits);
    }

    // allow receiving Ether from c when withdraw/withdrawAll transfer to this contract
    receive() external payable { }
}

