// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 withdrawValue) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeCbal = address(c).balance;
        bool reverted;
        try c.withdraw(withdrawValue) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterCbal = address(c).balance;
        assertTrue(afterCbal <= beforeCbal && afterDeposits == beforeDeposits);
    }

    function testFuzz_run(uint256 withdrawValue) public {
        _run(withdrawValue);
    }

    receive() external payable { }
}
